# Generates climb batch 10's MANIFEST block (CLIMB-BATCH-10.md, rungs W, C, G and N) from section 3 of the record
# and the briefing and checks lists of lists10.py, into $OUT10/manifest10.js ($FORTRESS_HOME/tmp by default, which is
# ignored); check10.js checks it. Copied from explorations/compile-ladder/plan-9/manifest/gen9.py as Fable's review left
# it: each tail is its rung's section word for word with the code-span backticks dropped, ASCII only, then its briefing
# entry by entry with one reason line each. The record holds no copy of the block (its section 7 says so), so the block
# is spliced into the script at the launch from this output alone. One value is set at launch and nowhere else:
# LEDGER_FROM, which the block refuses to load without. No rung declares an expectedCheckerCount, so the block has no
# CHECKER_BASE, and no rung lands only with another, so none has landsOnlyWith. Changed from gen9.py: the batch's values;
# the intro names item 20 as decided (Pavol's answer of 2026-10-03, POSITIONS.md, A type parameter the arguments do not
# fix takes its bound, its last sentence) and P1 as the one answer the coordinator writes in; W's expectedMinutes is
# raised by the coordinator if P1's answer is written into W's answers line.
#   python3 gen10.py [RECORD]      RECORD defaults to explorations/coordinator/CLIMB-BATCH-10.md
HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
from lists10 import LISTS, REASONS, IDS

ROOT = os.environ.get('FORTRESS_HOME', os.path.abspath(os.path.join(HERE, '../../../..')))
args = [a for a in sys.argv[1:] if not a.startswith('--')]
REC = args[0] if args else os.path.join(ROOT, 'explorations/coordinator/CLIMB-BATCH-10.md')
OUT = os.path.join(os.environ.get('OUT10', os.path.join(ROOT, 'tmp')), 'manifest10.js')   # tmp/ is ignored (.gitignore: /tmp/)
os.makedirs(os.path.dirname(OUT), exist_ok=True)
rec = open(REC).read()
s3 = rec[rec.index('\n## 3. The rungs\n'):rec.index('\n## 4. ')]
heads = list(re.finditer(r'^### ([A-Z])\. (.*), `([a-z0-9-]+)`$', s3, flags=re.M))
assert [h.group(1) for h in heads] == list(IDS), [h.group(1) for h in heads]

META = {   # expectedMinutes sets the scatter's start order only; under P1's answer the coordinator sets W's to 250
  'W': dict(path='/home/user/fortress-walkmeet', minutes=200, writesState=False, testIsStage=False),
  'C': dict(path='/home/user/fortress-checkdefects', minutes=260, writesState=False, testIsStage=False),
----
// Splices climb batch 10's MANIFEST block into a scratch copy of the workflow script and checks it, in the form of
// explorations/compile-ladder/plan-9/manifest/check9.js: node --check on the original and the spliced copy; the
// spliced copy parsed as the body of an async function, as the Workflow harness parses it (FACTS, "node --check does
// not check the batch script as the Workflow harness parses it ..."); every line outside the block byte-identical;
// the launch value refused when unset; the rungs, their order, the scatter and the entries' fields; each tail equal to
// its rung's section of the record followed by its briefing's reasons, one per key in order; no backtick or non-ASCII
// character in any string the agents read; each checks list a sub-list of its briefing; no tail or intro asking for a
// test citation to be re-anchored (the rule went at 2040cd056); no tail, intro or skeptic paragraph asking a skeptic to
// see the test fail again, rebuild or re-run a stage (POSITIONS.md, Nothing is built or run twice on the same code); the
// record's section 7 holds no copy of the block. Its last line counts the problems. Reads $OUT10/manifest10.js
// (gen10.py's output) and writes the spliced copy beside it. It splices nothing into the tracked script.
//   node check10.js [RECORD]      RECORD defaults to explorations/coordinator/CLIMB-BATCH-10.md
const fs = require('fs')
const cp = require('child_process')
const path = require('path')
const ROOT = process.env.FORTRESS_HOME || path.resolve(__dirname, '../../../..')
const HERE = process.env.OUT10 || path.join(ROOT, 'tmp')
const SRC = path.join(ROOT, 'explorations/coordinator/climb-batch-workflow.js')
const REC = process.argv[2] || path.join(ROOT, 'explorations/coordinator/CLIMB-BATCH-10.md')
const block = fs.readFileSync(path.join(HERE, 'manifest10.js'), 'utf8')
const orig = fs.readFileSync(SRC, 'utf8')
const lines = orig.split('\n')
const mIdx = lines.findIndex(l => l.startsWith('// MANIFEST - the coordinator replaces'))
const start = mIdx - 1
if (!/^\/\/ =+$/.test(lines[start])) throw new Error('no rule above MANIFEST')
----
# The briefing and checks lists of climb batch 10's four rungs, W, C, G and N (CLIMB-BATCH-10.md, section 3), in batch
# 9's form (explorations/compile-ladder/plan-9/manifest/lists9.py). Each briefing entry is a pair: its facts-extract.sh
# key and one line on why it is there and what the rung does with it, naming what to take from the entry and what to
# check in the rest. gen10.py renders the lines at the end of each rung's tail, in the order of the briefing. A checks
# list is a sub-list of its briefing's keys. POSITIONS.md and FACTS.md entries are keyed by their bold titles, which
# survive the consolidations. `python3 lists10.py` checks every key with facts-extract.sh --check (each must match
# exactly one place) and every reason's form; it is run again on the tree the batch is cut from.
SRC = 'ProjectFortress/src/com/sun/fortress'
EV = SRC + '/interpreter/evaluator'
OVF = EV + '/values/OverloadedFunction.java'
TC = SRC + '/scala_src/typechecker'

STOPS = "Every stop reserved for Pavol is reversible: finish, list it in stopsMet with liftedBy citing this entry, and land."
GATE_BEFORE = "Your before is the last landed gate's tables (batch 9's), not a run of the stage on your unchanged base; run only the after, into tmp/."
TESTF = "Write the core problem as a clean minimal test first, see it fail through the harness, commit it alone; your skeptic reads that order in your transcript and builds nothing."

